using System;using System.Linq;using System.Collections.Generic;using System.Text;using System.Text.Json;using System.Threading;using System.Threading.Tasks;using System.Net;using System.Net.Http;
namespace CalendarWeather;
internal static class SubscriptionTests {
 internal static async Task<Dictionary<string,bool>> Run(){var results=new Dictionary<string,bool>();string ics=string.Join("\r\n",new[]{"BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//Fixture//Calendar Test//EN","BEGIN:VEVENT","UID:daily","DTSTART:20261027T090000Z","DTEND:20261027T100000Z","RRULE:FREQ=DAILY;COUNT=3","EXDATE:20261028T090000Z","SUMMARY:Equipe\\, planejamento\\nReunião","END:VEVENT","BEGIN:VEVENT","UID:daily","RECURRENCE-ID:20261029T090000Z","DTSTART:20261029T120000Z","DTEND:20261029T130000Z","SUMMARY:Reagendado","END:VEVENT","BEGIN:VEVENT","UID:all-day","DTSTART;VALUE=DATE:20261028","DTEND;VALUE=DATE:20261029","SUMMARY:Dia inteiro","END:VEVENT","BEGIN:VEVENT","UID:cancelled","DTSTART:20261030T090000Z","DTEND:20261030T100000Z","STATUS:CANCELLED","SUMMARY:Cancelado","END:VEVENT","BEGIN:VEVENT","UID:dst","DTSTART;TZID=America/New_York:20261031T090000","DTEND;TZID=America/New_York:20261031T100000","RRULE:FREQ=DAILY;COUNT=3","SUMMARY:Fuso","END:VEVENT","END:VCALENDAR"});
 var account=new Account{Provider="Ics",FeedUrl="webcal://calendar.example.test/feed.ics?token=private-test-token",Email="Assinatura de exemplo",SourceName="Exemplo"};var snapshot=Services.ParseSubscription(ics,account,new DateTimeOffset(2026,10,27,0,0,0,TimeSpan.Zero));results["recurrenceExceptionsAndCancellation"]=snapshot.Events.Count==6&&!snapshot.Events.Any(e=>e.Title=="Cancelado")&&snapshot.Events.Any(e=>e.Title=="Reagendado"&&e.Start.UtcDateTime.Hour==12);results["allDayExclusiveEnd"]=snapshot.Events.Single(e=>e.AllDay).End-snapshot.Events.Single(e=>e.AllDay).Start==TimeSpan.FromDays(1);var dst=snapshot.Events.Where(e=>e.Title=="Fuso").OrderBy(e=>e.Start).ToArray();results["dstTimezone"]=dst.Length==3&&dst[0].Start.UtcDateTime.Hour==13&&dst[1].Start.UtcDateTime.Hour==14;results["escapedSummary"]=snapshot.Events.Any(e=>e.Title.Contains(",")&&e.Title.Contains("\n"));results["feedTokenExcludedFromCache"]=!JsonSerializer.Serialize(snapshot).Contains("private-test-token");results["existingGoogleAccountCompatible"]=JsonSerializer.Deserialize<Account>("{\"Email\":\"existing\"}")?.Provider=="Google";
 var bytes=Encoding.UTF8.GetBytes(JsonSerializer.Serialize(account));results["subscriptionAddressProtected"]=Store.Unprotect(Store.Protect(bytes)).SequenceEqual(bytes);
 var handler=new FixtureHandler(ics);var service=new Services(handler);await service.Subscription(account,CancellationToken.None);results["webcalUsesHttps"]=handler.Scheme=="https";bool rejected=false;try{Services.SubscriptionUri("http://example.test/calendar.ics");}catch(InvalidOperationException){rejected=true;}results["insecureSubscriptionRejected"]=rejected;
 return results;}
 sealed class FixtureHandler:HttpMessageHandler {readonly string ics;public string Scheme="";public FixtureHandler(string ics){this.ics=ics;}protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Scheme=request.RequestUri!.Scheme;return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(ics,Encoding.UTF8,"text/calendar")});}}
}
